begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
insert into auth.users(id,email_confirmed_at) values (md5('progress_a')::uuid,clock_timestamp()),(md5('progress_b')::uuid,clock_timestamp());
insert into profiles(id,display_name) values(md5('progress_a')::uuid,'A'),(md5('progress_b')::uuid,'B');
create function pg_temp.workout(key text,days integer,kind text default 'elapsed',outcome text default 'completed') returns uuid language plpgsql as $$
declare start_time timestamptz:=(current_date-days)::timestamp+interval '12 hours'; uid uuid:=md5('progress_a')::uuid; result uuid:=md5(key)::uuid;
begin insert into public.workout_sessions(id,owner_id,name,status,started_at,finished_at,effective_finished_at,duration_kind,activity_evidence_at,recognition_enabled) values(result,uid,key,outcome,start_time,case when outcome<>'in_progress' then start_time+interval '1 hour' end,case when outcome<>'in_progress' and kind in('elapsed','estimated') then start_time+interval '1 hour' end,kind,start_time+interval '30 minutes',true);return result;end $$;
create function pg_temp.performance(key text,slug text,reps integer,kg numeric,typ text default 'working',mode text default 'external') returns uuid language plpgsql as $$
declare item uuid; owner uuid:=md5('progress_a')::uuid; ex uuid; result uuid:=gen_random_uuid(); pos integer;
begin
 select e.id into ex from public.exercises e where e.slug=$2;
 select id into item from public.workout_exercises where workout_session_id=md5(key)::uuid and exercise_id=ex;
 if item is null then
 select coalesce(max(position),0)+1 into pos from public.workout_exercises where workout_session_id=md5(key)::uuid;
 insert into public.workout_exercises(owner_id,workout_session_id,position,exercise_id,exercise_name_snapshot) values(owner,md5(key)::uuid,pos,ex,slug) returning id into item;end if;
 select coalesce(max(position),0)+1 into pos from public.workout_sets where workout_exercise_id=item;
 insert into public.workout_sets(id,owner_id,workout_exercise_id,position,status,set_type,load_mode,actual_reps,actual_weight_kg,completed_at) values(result,owner,item,pos,'completed',typ,mode,reps,kg,(select started_at+interval '5 minutes'*pos from public.workout_sessions where id=md5(key)::uuid));return result;
end $$;
select pg_temp.workout('p_base',120);
select pg_temp.performance('p_base','barbell_bench_press',3,80);
select pg_temp.performance('p_base','barbell_bench_press',5,100);
select pg_temp.workout('p_dominated',5);
select pg_temp.performance('p_dominated','barbell_bench_press',3,100);
select pg_temp.workout('p_tradeoff',4,'estimated');
select pg_temp.performance('p_tradeoff','barbell_bench_press',3,106);
select pg_temp.workout('p_reps',3,'legacy');
select pg_temp.performance('p_reps','barbell_bench_press',10,90);
select pg_temp.workout('p_current',2);
select pg_temp.performance('p_current','barbell_bench_press',3,110);
select pg_temp.performance('p_current','barbell_bench_press',5,110);
select pg_temp.performance('p_current','barbell_bench_press',3,900,'warm_up');
select ok(not has_function_privilege('anon','public.exercise_progress(uuid,text,text,numeric,text,integer)','execute'),'anonymous exercise aggregates denied');
select ok(not has_function_privilege('service_role','public.training_progress(text,text,date,uuid)','execute'),'no service analytics shortcut');
select ok((select bool_and(not prosecdef) from pg_proc where proname in('performance_source','performance_metrics','exercise_progress','training_progress','progress_window','achievement_candidates')),'all new aggregates are invoker functions');
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('progress_a')::uuid,'role','authenticated')::text,true);
select is(workout_achievements(md5('p_dominated')::uuid),'[]'::jsonb,'100 x 5 historical performance suppresses celebration of improved 100 x 3');
select is((select max(value) from record_metrics((select id from exercises where slug='barbell_bench_press')) where session_id=md5('p_dominated')::uuid and metric='actual_rm' and load_key=3),100::numeric,'suppression does not erase exact three-rep performance');
select ok(exists(select 1 from jsonb_array_elements(workout_achievements(md5('p_tradeoff')::uuid))a where a->>'metric'='actual_rm'),'106 x 3 is not dominated by 100 x 5');
select ok(exists(select 1 from jsonb_array_elements(workout_achievements(md5('p_reps')::uuid))a where a->>'metric'='estimated_1rm'),'90 x 10 tradeoff remains eligible against 106 x 3');
select ok(exists(select 1 from jsonb_array_elements(workout_achievements(md5('p_current')::uuid))a where a->>'metric'='actual_rm' and a->>'load_key'='3' and a->>'dominated_in_session'='true'),'genuine improved triple remains a candidate when a current five is stronger');
select ok(exists(select 1 from jsonb_array_elements(workout_achievements(md5('p_current')::uuid))a where a->>'metric'='actual_rm' and a->>'load_key'='5' and a->>'dominated_in_session'='false'),'stronger current five is preferred without rewriting triple');
select is(workout_achievements(md5('p_base')::uuid),'[]'::jsonb,'first baseline not recognized');
select is(workout_achievements(md5('p_current')::uuid),workout_achievements(md5('p_current')::uuid),'refresh stable recognition');
select is((history_achievement_counts(array[md5('p_dominated')::uuid])->>(md5('p_dominated')::uuid)::text),null::text,'suppressed historical achievement counts agree');
select is((select jsonb_array_length(s->'points') from jsonb_array_elements(exercise_progress((select id from exercises where slug='barbell_bench_press'),'90','UTC')->'series')s where s->>'metric'='heaviest'),4,'range filters sessions before metric aggregation');
select is((select jsonb_array_length(s->'points') from jsonb_array_elements(exercise_progress((select id from exercises where slug='barbell_bench_press'),'all','UTC')->'series')s where s->>'metric'='heaviest'),5,'all-time includes old baseline');
select is((select (s->'points'->0->>'value')::numeric from jsonb_array_elements(exercise_progress((select id from exercises where slug='barbell_bench_press'))->'series')s where s->>'metric'='heaviest'),100::numeric,'real dates ordered oldest first');
select is((select (s->'points'->3->>'value')::numeric from jsonb_array_elements(exercise_progress((select id from exercises where slug='barbell_bench_press'))->'series')s where s->>'metric'='volume'),880::numeric,'session volume sums normal completed working sets without warm-up');
select is(jsonb_array_length(exercise_progress((select id from exercises where slug='incline_barbell_bench_press'))->'series'),0,'different exercise never merged into charts');
select throws_ok($$select progress_window('bad','UTC')$$,'22023',null,'invalid range denied');
select throws_ok($$select progress_window('90','Not/AZone')$$,'22023',null,'invalid timezone denied');
select throws_ok($$select exercise_progress((select id from exercises where slug='barbell_bench_press'),'90','UTC',0,'loaded')$$,'22023',null,'invalid comparable load denied');
select throws_ok($$select training_progress('90','UTC','2026-01-15')$$,'22023',null,'midmonth calendar input denied');
select is(((progress_window('30','America/Los_Angeles')->>'until_day')::date-(progress_window('30','America/Los_Angeles')->>'from_day')::date),30,'range is civil days, not fixed UTC hours');
reset role;
select pg_temp.performance('p_current','pull_up',12,null,'working','bodyweight');
select pg_temp.performance('p_current','pull_up',6,20);
select pg_temp.performance('p_current','forearm_plank',100,null,'working','bodyweight');
select pg_temp.performance('p_current','assisted_pull_up_machine',100,900);
insert into exercises(id,owner_id,name,slug,exercise_type) values(md5('p_custom')::uuid,md5('progress_a')::uuid,'Unclassified custom','p_private_custom','compound');
select pg_temp.performance('p_current','p_private_custom',10,20);
update exercises set archived_at=now() where id=md5('p_custom')::uuid;
update workout_sessions set idle_intervals='[{"from":"2026-01-01","to":"2026-01-02"}]'::jsonb where id=md5('p_current')::uuid;
select pg_temp.workout('p_same_day',2,'unknown');
select pg_temp.workout('p_abandoned',1,'elapsed','abandoned');
select pg_temp.performance('p_abandoned','barbell_bench_press',5,1000);
select pg_temp.workout('p_active',0,'unknown','in_progress');
select pg_temp.performance('p_active','barbell_bench_press',5,2000);
set local role authenticated;
select is((training_progress()->'summary'->>'completed_workouts')::int,5,'only completed sessions in range, including two on same day');
select is((training_progress()->'summary'->>'training_days')::int,4,'same local day counts one training day');
select is((training_progress()->>'working_sets')::int,8,'working-set total counts each eligible set once across exercises/muscles');
select is((training_progress()->'summary'->>'reliable_durations')::int,1,'only normal finish with evidence and no idle gap qualifies');
select is((training_progress()->'summary'->>'average_seconds')::numeric,3600::numeric,'average excludes estimates, legacy, unknown and idle intervals');
select is((training_progress()->'summary'->>'estimated_durations')::int,1,'estimates disclosed separately');
select is((training_progress()->'summary'->>'unreliable_durations')::int,3,'missing legacy and resumed elapsed durations disclosed');
select is((select sum((w->>'bodyweight_reps')::int)::int from jsonb_array_elements(training_progress()->'weekly')w),12,'unweighted bodyweight repetitions distinct from added resistance');
select ok(exists(select 1 from jsonb_array_elements(training_progress()->'muscles')m where m->>'name'='Unclassified' and (m->>'primary_sets')::int=1),'unclassified custom exercise not guessed');
select ok(exists(select 1 from jsonb_array_elements(training_progress()->'muscles')m where (m->>'secondary_sets')::int>0),'secondary muscle exposure distinct');
select ok(exists(select 1 from jsonb_array_elements(exercise_progress(md5('p_custom')::uuid)->'series')s where s->>'metric'='volume'),'archived own custom history stays available');
select is(jsonb_array_length(exercise_progress((select id from exercises where slug='forearm_plank'))->'series'),0,'unsupported duration no invented charts');
select is(jsonb_array_length(exercise_progress((select id from exercises where slug='assisted_pull_up_machine'))->'series'),0,'assistance never treated as added load');
select ok(exists(select 1 from jsonb_array_elements(exercise_progress((select id from exercises where slug='pull_up'))->'series')s where s->>'category'='bodyweight' and s->>'metric'='bodyweight_reps'),'bodyweight reps chart available');
select ok(exists(select 1 from jsonb_array_elements(exercise_progress((select id from exercises where slug='pull_up'))->'series')s where s->>'category'='added' and s->>'metric'='added_load'),'added load chart kept separate');
select ok(not exists(select 1 from jsonb_array_elements(exercise_progress((select id from exercises where slug='pull_up'))->'series')s where s->>'metric'='estimated_1rm'),'no invented bodyweight force estimate');
select is((select max((p->>'value')::numeric) from jsonb_array_elements(exercise_progress((select id from exercises where slug='barbell_bench_press'))->'series')s cross join jsonb_array_elements(s->'points')p where s->>'metric'='heaviest'),110::numeric,'active and abandoned performances excluded');
select set_config('request.jwt.claims',json_build_object('sub',md5('progress_b')::uuid,'role','authenticated')::text,true);
select is((training_progress()->'summary'->>'completed_workouts')::int,0,'foreign aggregate counts hidden');
select is(training_progress()->'muscles','[]'::jsonb,'foreign muscle exposure hidden');
select is(training_progress()->'calendar','[]'::jsonb,'foreign calendar hidden');
select is(exercise_progress(md5('p_custom')::uuid)->'series','[]'::jsonb,'foreign private exercise charts hidden');
select is(achievement_candidates(array[md5('p_current')::uuid]),'[]'::jsonb,'foreign recognition hidden');
reset role;
do $$begin for i in 1..220 loop perform pg_temp.workout('p_bulk'||i,400+i);perform pg_temp.performance('p_bulk'||i,'barbell_bench_press',3,50);end loop;end $$;
select pg_temp.workout('p_dst1',0);select pg_temp.workout('p_dst2',0);
update workout_sessions set started_at='2026-03-08T09:30:00Z',finished_at='2026-03-08T10:30:00Z',effective_finished_at='2026-03-08T10:30:00Z' where id=md5('p_dst1')::uuid;
update workout_sessions set started_at='2026-03-08T10:30:00Z',finished_at='2026-03-08T11:30:00Z',effective_finished_at='2026-03-08T11:30:00Z' where id=md5('p_dst2')::uuid;
select pg_temp.performance('p_dst1','barbell_bench_press',3,40);select pg_temp.performance('p_dst2','barbell_bench_press',3,40);
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('progress_a')::uuid,'role','authenticated')::text,true);
select ok((select bool_and(jsonb_array_length(s->'points')<=180) from jsonb_array_elements(exercise_progress((select id from exercises where slug='barbell_bench_press'),'all','UTC')->'series')s),'years of history return at most 180 real points per series');
select is((select (s->>'total_points')::int from jsonb_array_elements(exercise_progress((select id from exercises where slug='barbell_bench_press'),'all','UTC')->'series')s where s->>'metric'='heaviest'),227,'downsampling discloses full underlying session count');
select is((select max(value) from record_metrics((select id from exercises where slug='barbell_bench_press')) where metric='heaviest'),110::numeric,'current personal best not truncated by chart downsampling');
select is((select (d->>'workouts')::int from jsonb_array_elements(training_progress('all','America/Los_Angeles','2026-03-01')->'calendar')d where d->>'day'='2026-03-08'),2,'DST jump keeps separate sessions on same local training day');
select is((select count(*)::int from performance_source((select id from exercises where slug='barbell_bench_press'),null,'2026-03-08T09:30:00Z','2026-03-08T10:30:00Z')),1,'server date boundaries include start and exclude end');
select is(exercise_progress((select id from exercises where slug='barbell_bench_press'),'all','UTC'),exercise_progress((select id from exercises where slug='barbell_bench_press'),'all','UTC'),'sample ordering and bucket selection deterministic');
select * from finish();rollback;
